struct ZigzagIterator{a:Vec<i32>,b:Vec<i32>,i:usize,j:usize,t:bool}impl ZigzagIterator{fn new(a:Vec<i32>,b:Vec<i32>)->Self{Self{a,b,i:0,j:0,t:false}}fn next(&mut self)->i32{if(!self.t&&self.i<self.a.len())||self.j==self.b.len(){self.t=true;let x=self.a[self.i];self.i+=1;x}else{self.t=false;let x=self.b[self.j];self.j+=1;x}}fn has_next(&self)->bool{self.i<self.a.len()||self.j<self.b.len()}}
